package wb;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import org.json.*;
/** Standard Android GPS/network provider access. No root or shell; optional background reverse geocoding. */
public final class LocationReader {
 final Context ctx;final Handler main=new Handler(Looper.getMainLooper());final LocationManager manager;final AddressResolver addresses;Location fix;boolean registered,enabled;long revision;String state="未启用定位";
 LocationReader(Context c){ctx=c;manager=c.getSystemService(LocationManager.class);addresses=new AddressResolver(SystemClock::elapsedRealtime,(provider,key,lat,lon)->NativeAddress.lookup(c,provider,key,lat,lon));}
 public boolean permitted(){return ctx.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||ctx.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 final LocationListener listener=new LocationListener(){public void onLocationChanged(Location l){accept(l);}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){synchronized(LocationReader.this){state="等待新定位";}stopUpdates();refresh();}public void onProviderDisabled(String p){synchronized(LocationReader.this){state="定位源已关闭或等待其他定位源";}stopUpdates();refresh();}};
 synchronized void accept(Location candidate){if(!enabled||candidate==null)return;if(candidate.getElapsedRealtimeNanos()<=0){if(fix==null)state="定位缺少可靠时间，等待新位置";return;}long now=SystemClock.elapsedRealtimeNanos();long age=(now-candidate.getElapsedRealtimeNanos())/1000000;String bad=LocationPolicy.rejection(candidate.getLatitude(),candidate.getLongitude(),candidate.hasAccuracy()?candidate.getAccuracy():Double.NaN,age,candidate.isFromMockProvider());if(bad!=null){if(fix==null)state=bad;return;}if(fix==null||candidate.getElapsedRealtimeNanos()>fix.getElapsedRealtimeNanos()){fix=new Location(candidate);state="已取得定位";addresses.consider(fix.getLatitude(),fix.getLongitude(),fix.getAccuracy());}}
 public void configure(boolean on,JSONObject config){addresses.configure(on&&config.optBoolean("address",true),config.optString("addressProvider","system"),config.optString("amapKey",""));final long token;synchronized(this){enabled=on;token=++revision;if(!on){fix=null;state="定位已关闭，不发送位置";}}main.post(()->{synchronized(LocationReader.this){if(token!=revision)return;}stopUpdates();refresh();});}
 void refresh(){synchronized(this){if(!enabled||!permitted()){stopUpdates();fix=null;state=enabled?"未授予定位权限":"定位已关闭，不发送位置";return;}}
  if(manager==null){synchronized(this){state="系统没有定位服务";}return;}
  boolean available=false,attached=false;
  try{if(!manager.isLocationEnabled()){stopUpdates();synchronized(this){fix=null;state="系统定位开关未开启";}return;}
   for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}){try{if(!manager.isProviderEnabled(provider))continue;available=true;accept(manager.getLastKnownLocation(provider));if(!registered){manager.requestLocationUpdates(provider,5000,0,listener,Looper.getMainLooper());attached=true;}}catch(SecurityException denied){}catch(IllegalArgumentException missing){}}
   registered=registered||attached;synchronized(this){if(!available){state="无可用 GPS/网络定位源";fix=null;}else if(!registered)state="定位请求被拒绝，请检查权限";else if(fix==null)state="等待定位，可将车停在开阔处";}
  }catch(SecurityException e){synchronized(this){state="系统拒绝定位权限";fix=null;}}
 }
 void stopUpdates(){if(manager!=null)try{manager.removeUpdates(listener);}catch(Exception ignored){}registered=false;}
 public synchronized JSONObject snapshot(boolean include){JSONObject out=new JSONObject();try{out.put("status",!include?"disabled":!permitted()?"permission_required":state);if(!include||!enabled||!permitted()||manager==null||!manager.isLocationEnabled()||fix==null)return out;long age=(SystemClock.elapsedRealtimeNanos()-fix.getElapsedRealtimeNanos())/1000000;String bad=LocationPolicy.rejection(fix.getLatitude(),fix.getLongitude(),fix.getAccuracy(),age,fix.isFromMockProvider());if(bad!=null){out.put("status",bad);return out;}out.put("status","available");out.put("latitude",fix.getLatitude());out.put("longitude",fix.getLongitude());out.put("coordinate_system","WGS84 (Android Location)");out.put("accuracy_m",Math.round(fix.getAccuracy()));out.put("age_seconds",age/1000);out.put("provider",fix.getProvider());addresses.consider(fix.getLatitude(),fix.getLongitude(),fix.getAccuracy());JSONObject parsed=addresses.snapshot(fix.getLatitude(),fix.getLongitude(),fix.getAccuracy());java.util.Iterator<String> names=parsed.keys();while(names.hasNext()){String name=names.next();out.put(name,parsed.get(name));}out.put("address_note","Use only returned address components, respecting accuracy and approximate nearby labels. Do not invent missing city, street, destination or weather.");}catch(Exception ignored){}return out;}
 public void awaitAddress(){addresses.await(2000);}
 public void close(){configure(false,new JSONObject());}
}
